/bin/bash -lc "node <<'NODE'
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const html = fs.readFileSync('/workspace/star-garden.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
new vm.Script(script);
function run(reduced) {
  const nodes = new Map();
  const noop = () => {};
  const context = new Proxy({}, { get: (target, key) => target[key] || noop });
  context.createRadialGradient = () => ({ addColorStop: noop });
  function node(id) {
    if ("'!nodes.has(id)) nodes.set(id, { textContent: '"'', events: {}, attrs: {},
      addEventListener(type, fn) { this.events[type] = fn; },
      setAttribute(key, value) { this.attrs[key] = value; },
      getBoundingClientRect: () => ({ width: 1200, height: 800, left: 0, top: 0 }),
      getContext: () => context, setPointerCapture: noop,
      toBlob: fn => fn({ type: 'image/png' }), click() { this.clicked = true; }, remove: noop });
    return nodes.get(id);
  }
  const scheduled = new Map();
  let frameId = 0, saved;
  const document = { hidden: false, getElementById: node, addEventListener: noop,
    body: { appendChild: noop }, createElement() { saved = node('download'); return saved; } };
  const sandbox = { document, Math, devicePixelRatio: 1,
    matchMedia: () => ({ matches: reduced, addEventListener: noop }),
    requestAnimationFrame: fn => { scheduled.set(++frameId, fn); return frameId; },
    cancelAnimationFrame: id => scheduled.delete(id),
    ResizeObserver: class { observe() {} },
    URL: { createObjectURL: () => 'blob:test', revokeObjectURL: noop }, setTimeout: noop };
  vm.runInNewContext(script, sandbox);
  assert.equal(node('count').textContent, '7 stars planted');
  assert.equal(scheduled.size, reduced ? 0 : 1);
  node('plant').events.click();
  assert.equal(node('count').textContent, '8 stars planted');
  node('sky').events.pointerdown({ button: 0, pointerId: 1, clientX: 400, clientY: 300 });
  node('sky').events.pointermove({ pointerId: 1, clientX: 401, clientY: 300 });
  assert.equal(node('count').textContent, '9 stars planted');
  node('sky').events.pointermove({ pointerId: 1, clientX: 450, clientY: 300 });
  node('sky').events.pointerup({ pointerId: 1 });
  assert.equal(node('count').textContent, '10 stars planted');
  for (let i = 0; i < 150; i++) node('plant').events.click();
  assert.equal(node('count').textContent, '140 stars planted');
  node('pause').events.click();
  assert.equal(node('pause').attrs['aria-pressed'], String("'!reduced));
  assert.equal(scheduled.size, reduced ? 1 : 0);
  node('"'save').events.click();
  assert.equal(saved.download, 'my-star-garden.png');
  assert.equal(saved.clicked, true);
  node('clear').events.click();
  assert.equal(node('count').textContent, '0 stars planted');
  node('plant').events.click();
  assert.equal(node('count').textContent, '1 star planted');
}
run(false);
run(true);
console.log('Passed: JavaScript syntax; planting and drag spacing; star limit; pause/resume; reduced-motion default; PNG download trigger; clear and replant.');
NODE"

